// Design Atlas 3.1 modules: image-ready layouts and data visuals. Every data-media slot accepts an uploaded image.
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const def=(id,name,category,description,mood,props,tags,fields={})=>({id,name,category,description,mood,props,tags,fields});
const rows=(v,max=20)=>String(v||'').split('\n').map(x=>x.trim()).filter(Boolean).slice(0,max).map(s=>s.split('|').map(x=>esc(x.trim())));
const br=v=>esc(v).replaceAll('\n','<br>');
const head=(p,cls='')=>`<header class="section-heading ${cls}"><span class="eyebrow" data-f="eyebrow">${esc(p.eyebrow)}</span><h2 data-f="title">${br(p.title)}</h2><p data-f="subtitle">${esc(p.subtitle)}</p></header>`;
const btn=(t,secondary=false,f='')=>t?`<button type="button" class="btn${secondary?' secondary':''}" data-demo${f?` data-f="${f}"`:''}>${esc(t)}${secondary?'':' <span aria-hidden="true">↗</span>'}</button>`:'';
const acts=p=>`<div class="actions">${btn(p.button,false,'button')}${btn(p.secondary,true,'secondary')}</div>`;
const ph=(slot,i=0,extra='')=>`<div class="ph ph-${i%6}${extra?' '+extra:''}" data-media="${slot}" aria-hidden="true"><i></i></div>`;

