const R={
 'image-hero':p=>`${ph('bg',3,'ih-media')}<div class="ih-shade" aria-hidden="true"></div><div class="ih-copy"><span class="eyebrow" data-f="eyebrow">${esc(p.eyebrow)}</span><h1 class="fx-title ih-title" data-f="title">${br(p.title)}</h1><p data-f="subtitle">${esc(p.subtitle)}</p>${acts(p)}</div><span class="ih-scroll" aria-hidden="true">SCROLL ↓</span>`,
 'split-media':p=>`<figure class="sm-figure">${ph('photo',1,'sm-photo')}<figcaption>FIG. 01 — ${esc(p.eyebrow)}</figcaption></figure><div class="sm-copy">${head(p)}<ul class="sm-list">${rows(p.items,8).map((x,i)=>`<li><b>0${i+1}</b>${x[0]}</li>`).join('')}</ul>${btn(p.button,false,'button')}</div>`,
 'gallery-masonry':(p,b)=>`${head(p)}<div class="masonry" data-masonry>${rows(p.items,12).map((x,i)=>`<button type="button" class="m-tile m-h${i%3}" data-lightbox aria-label="放大查看：${x[0]}">${ph('photo-'+i,i)}<span class="m-cap"><b>${x[0]}</b><small>${x[1]||''}</small></span></button>`).join('')}</div><div class="lightbox" data-lightbox-view hidden><button type="button" class="lb-close" data-lightbox-close aria-label="关闭">✕</button><div class="lb-img"></div><p class="lb-cap"></p></div>`,
 'bento-media':p=>{const r=rows(p.items,3);return `${head(p)}<div class="bm-grid"><figure class="bm-cell bm-a">${ph('m-0',0)}<figcaption>${r[0]?.[0]||''}</figcaption></figure><div class="bm-cell bm-stat"><strong data-f="button">${esc(p.button)}</strong><span data-f="secondary">${esc(p.secondary)}</span></div><figure class="bm-cell bm-b">${ph('m-1',2)}<figcaption>${r[1]?.[0]||''}</figcaption></figure><figure class="bm-cell bm-c">${ph('m-2',4)}<figcaption>${r[2]?.[0]||''}</figcaption></figure><blockquote class="bm-cell bm-q">“一起做点小而美的事。”</blockquote></div>`},
 'image-marquee':p=>{const tiles=Array.from({length:8},(_,i)=>i);const line=hide=>tiles.map(i=>`<div class="im-tile" ${hide?'aria-hidden="true"':''}>${ph('tile-'+i,i)}</div>`).join('');return `<div class="center">${head(p)}</div><div class="im-track"><div>${line(false)}${line(true)}</div></div>`},
 'product-grid':p=>`<div class="pg-top">${head(p)}<span class="pg-bag" aria-live="polite">购物袋 <b data-bag-count>0</b></span></div><div class="pg-grid">${rows(p.items,8).map((x,i)=>`<article class="pg-item fx-card"><div class="pg-media">${ph('product-'+i,i+1)}${x[2]?`<span class="pg-tag">${x[2]}</span>`:''}</div><div class="pg-info"><h3>${x[0]}</h3><span>${x[1]||''}</span></div><button type="button" class="btn secondary pg-add" data-bag-add data-f="button">${esc(p.button)}</button></article>`).join('')}</div>`,
 'stats-rings':p=>`${head(p,'center')}<div class="rings">${rows(p.items,6).map(x=>{const v=Math.max(0,Math.min(100,parseFloat(x[0])||0));return `<figure class="ring"><svg viewBox="0 0 120 120" aria-hidden="true"><circle cx="60" cy="60" r="52" class="ring-bg"/><circle cx="60" cy="60" r="52" class="ring-fg" style="--v:${v}"/></svg><strong>${x[0]}<small>${x[2]||''}</small></strong><figcaption>${x[1]||''}</figcaption></figure>`}).join('')}</div>`,
 'kpi-sparkline':p=>`${head(p)}<div class="spark-grid">${rows(p.items,6).map(x=>{const pts=String(x[3]||'').split(',').map(Number).filter(Number.isFinite).slice(0,40);const min=Math.min(...pts),max=Math.max(...pts),d=pts.length>1?pts.map((v,i)=>`${(i/(pts.length-1)*200).toFixed(1)},${(52-((v-min)/((max-min)||1))*44).toFixed(1)}`).join(' '):'0,30 200,30';const up=!String(x[2]||'').trim().startsWith('-');return `<article class="spark panel"><small>${x[0]}</small><strong>${x[1]||''}</strong><span class="${up?'up':'down'}">${up?'↗':'↘'} ${x[2]||''}</span><svg viewBox="0 0 200 56" preserveAspectRatio="none" aria-hidden="true"><polyline points="${d}" pathLength="100"/></svg></article>`}).join('')}</div>`,
 'timeline-vertical':p=>`${head(p,'center')}<div class="vt" data-vtimeline><div class="vt-line" aria-hidden="true"><i></i></div>${rows(p.items,10).map((x,i)=>`<article class="vt-item ${i%2?'r':'l'}"><span class="vt-dot" aria-hidden="true"></span><time>${x[0]}</time><h3>${x[1]||''}</h3><p>${x[2]||''}</p></article>`).join('')}</div>`,
 'steps-numbered':p=>`${head(p)}<ol class="steps-n">${rows(p.items,6).map((x,i)=>`<li class="fx-card"><span class="sn-num">${String(i+1).padStart(2,'0')}</span><h3>${x[0]}</h3><p>${x[1]||''}</p></li>`).join('')}</ol>`,
 'hover-reveal':p=>`${head(p)}<div class="hr-grid">${rows(p.items,6).map((x,i)=>`<article class="hr-card" tabindex="0">${ph('card-'+i,i+2)}<div class="hr-body"><span class="hr-tag">${x[2]||''}</span><h3>${x[0]}</h3><p>${x[1]||''}</p><span class="hr-more">查看项目 →</span></div></article>`).join('')}</div>`,
 'rotating-words':p=>{const w=rows(p.items,8).map(x=>x[0]);return `<div class="rw"><span class="eyebrow" data-f="eyebrow">${esc(p.eyebrow)}</span><h2 class="rw-title fx-title"><span data-f="title">${esc(p.title)}</span> <span class="rw-words" data-rotate>${w.map((x,i)=>`<span class="${i===0?'on':''}">${x}</span>`).join('')}</span></h2><p data-f="subtitle">${esc(p.subtitle)}</p>${btn(p.button,false,'button')}</div>`},
 'parallax-hero':p=>`<div class="px-layers" data-parallax aria-hidden="true">${ph('bg',5,'px-bg')}<i class="px-l1" style="--d:.6"></i><i class="px-l2" style="--d:1.2"></i><i class="px-l3" style="--d:2"></i><i class="px-l4" style="--d:3"></i></div><div class="px-copy center">${head(p)}${acts(p)}</div>`,
 'contact-card':p=>`<div class="cc-copy">${head(p)}<dl class="cc-list">${rows(p.items,8).map(x=>`<div><dt>${x[0]}</dt><dd><span>${x[1]||''}</span><button type="button" data-copy-text="${x[1]||''}" aria-label="复制${x[0]}">复制</button></dd></div>`).join('')}</dl></div><div class="cc-map">${ph('map',2,'cc-map-img')}<span class="cc-pin" aria-hidden="true">✳</span></div>`,
 'social-links':p=>`<div class="center">${head(p)}</div><div class="sl-list">${rows(p.items,12).map((x,i)=>`<a class="sl-pill" href="#top" data-nav-link><span class="sl-ico" aria-hidden="true">${['✎','✉','◈','◉','▤','✳'][i%6]}</span><b>${x[0]}</b><small>${x[1]||''}</small><i aria-hidden="true">↗</i></a>`).join('')}</div>`,
 'quote-image':p=>`<div class="qi">${ph('portrait',4,'qi-photo')}<div class="qi-copy"><span class="eyebrow" data-f="eyebrow">${esc(p.eyebrow)}</span><blockquote class="fx-title" data-f="title">${br(p.title)}</blockquote><p data-f="subtitle">— ${esc(p.subtitle)}</p>${btn(p.button,true,'button')}</div></div>`,
 'video-showcase':p=>`${head(p,'center')}<div class="vs" data-video><div class="vs-frame">${ph('poster',0,'vs-poster')}<button type="button" class="vs-play" data-video-toggle aria-pressed="false" aria-label="播放演示">▶</button><div class="vs-bar"><i></i></div><span class="vs-time" data-f="button">${esc(p.button)}</span></div></div>`
};
export function renderMedia(b){const fn=R[b.type];return fn?fn(b.props,b):null;}

