export const MEDIA_BLOCK_JS=String.raw`
(()=>{const hooks=window.__atlasHooks=window.__atlasHooks||[],reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
const onView=(el,fn)=>{if(!('IntersectionObserver' in window)){fn();return}const io=new IntersectionObserver(l=>{if(l[0].isIntersecting){io.disconnect();fn()}},{threshold:.3});io.observe(el)};
hooks.push((sec,{edit})=>{
 sec.querySelectorAll('.rings,.spark-grid').forEach(g=>{if(edit||reduce)return;g.classList.add('pending');onView(g,()=>requestAnimationFrame(()=>g.classList.remove('pending')))});
 sec.querySelectorAll('[data-rotate]').forEach(w=>{if(edit||reduce)return;const items=[...w.children];if(items.length<2)return;let i=0;const timer=setInterval(()=>{if(!document.contains(w)){clearInterval(timer);return}const cur=items[i];i=(i+1)%items.length;cur.classList.remove('on');cur.classList.add('out');items[i].classList.remove('out');items[i].classList.add('on');setTimeout(()=>cur.classList.remove('out'),650)},2400)});
});
const scroll=()=>{document.querySelectorAll('[data-vtimeline]').forEach(t=>{const r=t.getBoundingClientRect();const p=Math.max(0,Math.min(1,(innerHeight*.6-r.top)/r.height));t.style.setProperty('--tp',p.toFixed(3))})};
hooks.push(Object.assign(()=>{},{scroll}));
document.addEventListener('pointermove',e=>{const s=e.target.closest&&e.target.closest('main>section');const l=s&&s.querySelector('[data-parallax]');if(!l||reduce)return;const r=s.getBoundingClientRect();l.style.setProperty('--mx',((e.clientX-r.left)/r.width-.5).toFixed(3));l.style.setProperty('--my',((e.clientY-r.top)/r.height-.5).toFixed(3))},{passive:true});
const say=msg=>{const el=document.querySelector('.demo-toast');if(el){el.textContent=msg;el.classList.add('visible');clearTimeout(say.t);say.t=setTimeout(()=>el.classList.remove('visible'),2400)}};
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;
 if(t.matches('[data-lightbox]')){const sec=t.closest('section'),v=sec.querySelector('[data-lightbox-view]'),img=t.querySelector('[data-media]');v.querySelector('.lb-img').style.background=getComputedStyle(img).background;v.querySelector('.lb-cap').textContent=t.querySelector('.m-cap b')?.textContent||'';v.hidden=false;v.querySelector('[data-lightbox-close]').focus()}
 if(t.matches('[data-lightbox-close]')){const v=t.closest('[data-lightbox-view]');v.hidden=true}
 if(t.matches('[data-bag-add]')){const sec=t.closest('section'),c=sec.querySelector('[data-bag-count]'),bag=sec.querySelector('.pg-bag');c.textContent=Number(c.textContent)+1;bag.classList.add('bump');setTimeout(()=>bag.classList.remove('bump'),220);say('已加入演示购物袋，不会产生订单。')}
 if(t.matches('[data-copy-text]')){const v=t.dataset.copyText;(navigator.clipboard?navigator.clipboard.writeText(v):Promise.reject()).then(()=>{t.textContent='已复制'},()=>{t.textContent='请手动复制'}).finally(()=>setTimeout(()=>{t.textContent='复制'},1600))}
 if(t.matches('[data-video-toggle]')){const v=t.closest('[data-video]'),on=!v.hasAttribute('data-playing');v.toggleAttribute('data-playing',on);t.textContent=on?'❚❚':'▶';t.setAttribute('aria-pressed',on);t.setAttribute('aria-label',on?'暂停演示':'播放演示')}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('[data-lightbox-view]:not([hidden])').forEach(v=>v.hidden=true)});
})();`;
